import{_ as e,o as a,c as o,a2 as s}from"./chunks/framework.sN6AQ-fu.js";const g=JSON.parse('{"title":"The app at a glance","description":"","frontmatter":{},"headers":[],"relativePath":"suite/overview.md","filePath":"suite/overview.md"}'),r={name:"suite/overview.md"};function n(i,t,h,d,l,c){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="the-app-at-a-glance" tabindex="-1">The app at a glance <a class="header-anchor" href="#the-app-at-a-glance" aria-label="Permalink to &quot;The app at a glance&quot;">​</a></h1><p>Mayhem opens to <strong>Overview</strong>. The top bar switches between the workspaces; the robot chip shows the connection, and the gear opens <a href="/Mayhem/suite/projects#settings">Settings</a>. The <strong>Tasks</strong> tab shows a count when plans or changes are waiting for you.</p><table tabindex="0"><thead><tr><th>Workspace</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="#overview">Overview</a></td><td>Routine thumbnails, latest logs, the match-ready checklist and the robot explainer.</td></tr><tr><td><a href="/Mayhem/suite/changes">Changes</a></td><td>What a robot code change does: driver controls, state machines, values, hardware, autos, and a sim proof.</td></tr><tr><td><a href="/Mayhem/suite/tasks">Tasks</a></td><td>Team feedback that becomes agent tasks; approve plans and check changes.</td></tr><tr><td><a href="/Mayhem/suite/autonomous">Autonomous</a></td><td>Place pose goals on the field, add actions and conditions, preview the routine.</td></tr><tr><td><a href="/Mayhem/suite/state-machines">State machines</a></td><td>Routine and mechanism graphs, simulated, live over NT4 or replayed from a log.</td></tr><tr><td><a href="/Mayhem/suite/logs">Logs</a></td><td>Import and analyze <code>.wpilog</code> recordings: health, power, signals and pose replay.</td></tr><tr><td><a href="/Mayhem/suite/robot">Robot</a></td><td>What&#39;s on the robot now, every value in the code, specs and limits, connection and log collection.</td></tr></tbody></table><p>Most workspaces that read robot code (Changes, Tasks, Robot → On the robot now and Values, the explainer) need the <strong>desktop app</strong> and a <strong>robot code folder</strong>. Choose the folder once from any of them; the rest use the same one.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><ul><li><p><strong>Autonomous routines.</strong> A thumbnail per routine with its run time, marked <strong>Ready</strong> or <strong>Doesn&#39;t finish</strong>. Click one to open it in Autonomous.</p></li><li><p><strong>Latest logs.</strong> The newest recordings and whether their analysis is clean.</p></li><li><p><strong>Get to match-ready.</strong> Four checks, each with a button that takes you to the fix:</p><ol><li>A routine runs without errors.</li><li>The robot is connected.</li><li>Log collection is on.</li><li>The exported C++ matches the current project.</li></ol><p>Project errors and warnings are listed under the checklist.</p></li><li><p><strong>How the robot works.</strong> A clickable map of the robot read from its code. Click a part to see what it does, how the driver controls it, what it&#39;s doing right now (when connected) and its recent commits. Anyone can write or edit a part&#39;s plain-language description.</p></li></ul><h2 id="right-click-anything" tabindex="-1">Right-click anything <a class="header-anchor" href="#right-click-anything" aria-label="Permalink to &quot;Right-click anything&quot;">​</a></h2><p>Right-click a step, a state, a log moment, a finding or most other things to get <strong>Make this an agent task</strong>. The new task is pinned to what you clicked, so an agent knows exactly what you meant. See <a href="/Mayhem/suite/tasks">Tasks</a>.</p><h2 id="desktop-vs-browser" tabindex="-1">Desktop vs. browser <a class="header-anchor" href="#desktop-vs-browser" aria-label="Permalink to &quot;Desktop vs. browser&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Desktop app</th><th>Browser (<code>pnpm dev</code>)</th></tr></thead><tbody><tr><td>Autos, preview, state simulation, log analysis</td><td>Yes</td><td>Yes</td></tr><tr><td>Live file link to a project in the robot repo</td><td>Yes</td><td>Download snapshots only</td></tr><tr><td>Changes, Tasks, Values, On the robot now</td><td>Yes</td><td>Changes opens saved review files; feedback downloads as files</td></tr><tr><td>Log collection, AdvantageScope, deploy</td><td>Yes</td><td>No</td></tr></tbody></table><p>Install the desktop app from <a href="/Mayhem/guide/installation">Installation</a>.</p>',11)])])}const u=e(r,[["render",n]]);export{g as __pageData,u as default};
